(* [comment removed for export] *)
Lemma atexit_cellsA_frame : forall (M M' : word -> option byte) (ax : axv),
  (forall a : Z, AXLO <= a < AXHI -> M' (Z_to_bv 64 a) = M (Z_to_bv 64 a)) ->
